mapper.select:
SELECT 
FROM reservations
WHERE store_id = #{storeId}
  AND member_id = #{memberId}
  AND user_id IS NULL
ORDER BY reservation_date DESC

mapper.update:
UPDATE reservations
SET reservation_date = #{reservationDate},
    number = #{number}
WHERE id = #{reservationId}
  AND store_id = #{storeId}
  AND status != 'キャンセル'

UPDATE reservations
SET status = #{status}
WHERE id = #{reservationId}
  AND store_id = #{storeId}

